import time, sys
t = T("/workspace/executable nums.txt", w=60, h=12)
def watch(key, dur=1.0, lit=False):
    t0=time.time()
    if lit: t.lit(key, wait=0)
    else: t.k(key, wait=0.0)
    last=None
    while time.time()-t0 < dur:
        c = t.cap().splitlines()
        l = (c[-1] if c else '', c[0] if c else '')
