{"command":"rm -f /workspace/tmpmain.go; mkdir -p /workspace/config && cat > /workspace/config/config.go <<'EOF'
// Package config holds the configuration file structures.
package config

import (
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"

	"gopkg.in/yaml.v3"
)

// Config holds all the data that can be configured in the
// external configuration file
type Config struct {
	Action              map[string][]string             `json:"Action"`
	Keymap              map[string]string               `json:"Keymap"`
	InitialFilter       string                          `json:"InitialFilter"`
	Style               StyleSet                        `json:"Style"`
	Prompt              string                          `json:"Prompt"`
	Layout              string                          `json:"Layout"`
	OnCancel            OnCancelBehavior                `json:"OnCancel"`
	CustomFilter        map[string]CustomFilterConfig   `json:"CustomFilter"`
	QueryExecutionDelay int                             `json:"QueryExecutionDelay"`
	StickySelection     bool                            `json:"StickySelection"`
	MaxScanBufferSize   int                             `json:"MaxScanBufferSize"`
	FuzzyLongestSort    bool                            `json:"FuzzyLongestSort"`
	SuppressStatusMsg   bool                            `json:"SuppressStatusMsg"`
	SingleKeyJump       SingleKeyJumpConfig             `json:"SingleKeyJump"`
	SelectionPrefix     string                          `json:"SelectionPrefix"`
	ANSI                bool                            `json:"ANSI"`
	Height              string                          `json:"Height"`
}

// SingleKeyJumpConfig holds the configuration for single key jump mode
type SingleKeyJumpConfig struct {
	ShowPrefix bool `json:"ShowPrefix"`
}

// CustomFilterConfig is used to specify configuration parameters
// to CustomFilters
type CustomFilterConfig struct {
	Cmd             string   `json:"Cmd"`
	Args            []string `json:"Args"`
	BufferThreshold int      `json:"BufferThreshold"`
}

// OnCancelBehavior specifies what happens when the user cancels
type OnCancelBehavior string

const (
	OnCancelSuccess OnCancelBehavior = "success"
	OnCancelError   OnCancelBehavior = "error"
)

// ValidateOnCancel checks the value
func ValidateOnCancel(s string) (OnCancelBehavior, error) {
	switch s {
	case "", "success":
		return OnCancelSuccess, nil
	case "error":
		return OnCancelError, nil
	}
	return "", fmt.Errorf("invalid OnCancel value %q: must be \"success\" or \"error\"", s)
}

// UnmarshalText implements encoding.TextUnmarshaler
func (o *OnCancelBehavior) UnmarshalText(b []byte) error {
	v, err := ValidateOnCancel(string(b))
	if err != nil {
		return err
	}
	if len(b) == 0 {
		*o = ""
		return nil
	}
	*o = v
	return nil
}

// Layout types
const (
	LayoutTopDown            = "top-down"
	LayoutBottomUp           = "bottom-up"
	LayoutTopDownQueryBottom = "top-down-query-bottom"
)

// IsValidLayoutType checks the layout name
func IsValidLayoutType(s string) bool {
	switch s {
	case LayoutTopDown, LayoutBottomUp, LayoutTopDownQueryBottom:
		return true
	}
	return false
}

// Init sets the default values
func (c *Config) Init() {
	c.Keymap = make(map[string]string)
	c.InitialFilter = "IgnoreCase"
	c.Style.Init()
	c.Prompt = "QUERY>"
	c.Layout = LayoutTopDown
	c.OnCancel = OnCancelSuccess
	c.MaxScanBufferSize = 256
}

// ReadFilename reads the config from the given file
func (c *Config) ReadFilename(filename string) error {
	f, err := os.Open(filename)
	if err != nil {
		return fmt.Errorf("failed to open file %s: %w", filename, err)
	}
	defer f.Close()

	ext := strings.ToLower(filepath.Ext(filename))
	if ext == ".yaml" || ext == ".yml" {
		if err := decodeYAML(f, c); err != nil {
			return fmt.Errorf("failed to decode YAML: %w", err)
		}
	} else {
		if err := json.NewDecoder(f).Decode(c); err != nil {
			return fmt.Errorf("failed to decode JSON: %w", err)
		}
	}

	if !IsValidLayoutType(c.Layout) {
		return fmt.Errorf("invalid layout type: %s", c.Layout)
	}
	return nil
}

func decodeYAML(r io.Reader, c *Config) error {
	buf, err := io.ReadAll(r)
	if err != nil {
		return err
	}
	var v interface{}
	if err := yaml.Unmarshal(buf, &v); err != nil {
		return err
	}
	if v == nil {
		return nil
	}
	v = normalizeYAML(v)
	js, err := json.Marshal(v)
	if err != nil {
		return err
	}
	return json.Unmarshal(js, c)
}

func normalizeYAML(v interface{}) interface{} {
	switch x := v.(type) {
	case map[string]interface{}:
		m := make(map[string]interface{}, len(x))
		for k, vv := range x {
			m[k] = normalizeYAML(vv)
		}
		return m
	case map[interface{}]interface{}:
		m := make(map[string]interface{}, len(x))
		for k, vv := range x {
			m[fmt.Sprint(k)] = normalizeYAML(vv)
		}
		return m
	case []interface{}:
		for i := range x {
			x[i] = normalizeYAML(x[i])
		}
		return x
	}
	return v
}

// LocateRcfile attempts to find the config file in various locations
func LocateRcfile() (string, error) {
	var dirs []string
	home, _ := os.UserHomeDir()
	if xdg := os.Getenv("XDG_CONFIG_HOME"); xdg != "" {
		dirs = append(dirs, filepath.Join(xdg, "peco"))
	} else if home != "" {
		dirs = append(dirs, filepath.Join(home, ".config", "peco"))
	}
	if xdgdirs := os.Getenv("XDG_CONFIG_DIRS"); xdgdirs != "" {
		for _, d := range filepath.SplitList(xdgdirs) {
			if d == "" {
				continue
			}
			dirs = append(dirs, filepath.Join(d, "peco"))
		}
	} else {
		dirs = append(dirs, filepath.Join("/etc/xdg", "peco"))
	}
	if home != "" {
		dirs = append(dirs, filepath.Join(home, ".peco"))
	}
	for _, d := range dirs {
		for _, name := range []string{"config.json", "config.yaml", "config.yml"} {
			p := filepath.Join(d, name)
			if _, err := os.Stat(p); err == nil {
				return p, nil
			}
		}
	}
	return "", errors.New("config file not found")
}
EOF
echo ok"}

