	return []*optDef{
		{short: 'h', long: "help", kind: optBool, b: &opts.OptHelp},
		{long: "query", kind: optString, s: &opts.OptQuery},
		{long: "rcfile", kind: optString, s: &opts.OptRcfile},
		{long: "version", kind: optBool, b: &opts.OptVersion},
		{short: 'b', long: "buffer-size", kind: optInt, i: &opts.OptBufferSize},
		{long: "null", kind: optBool, b: &opts.OptEnableNullSep},
		{long: "initial-index", kind: optInt, i: &opts.OptInitialIndex},
		{long: "initial-filter", kind: optString, s: &opts.OptInitialFilter},
		{long: "prompt", kind: optString, s: &opts.OptPrompt},
		{long: "layout", kind: optString, s: &opts.OptLayout},
		{long: "select-1", kind: optBool, b: &opts.OptSelect1},
		{long: "exit-0", kind: optBool, b: &opts.OptExitZero},
		{long: "select-all", kind: optBool, b: &opts.OptSelectAll},
		{long: "on-cancel", kind: optString, s: &opts.OptOnCancel},
		{long: "selection-prefix", kind: optString, s: &opts.OptSelectionPrefix},
		{long: "exec", kind: optString, s: &opts.OptExec},
		{long: "print-query", kind: optBool, b: &opts.OptPrintQuery},
		{long: "ansi", kind: optBool, b: &opts.OptANSI},
		{long: "height", kind: optString, s: &opts.OptHeight},
	}
