		} else if canarg && !eof() {
			arg = pop()
			if argumentIsOption(arg) {
				isNum := d.kind == optInt && len(arg) > 1 && arg[0] == '-' && arg[1] >= '0' && arg[1] <= '9'
				if !isNum {
