				argument = &rest
				optname = optname[:pos]
			}
		}

		if islong {
			d, ok := longs[optname]
			if !ok {
				return nil, &flagError{fmt.Sprintf("unknown flag `%s'", optname)}
			}
			if err := parseOption(d, true, argument); err != nil {
				return nil, err
			}
			continue
		}

