					rest := optname[n:]
					argument = &rest
					optname = string(c)
				}
			}
		}

		for idx, c := range optname {
			d, ok := shorts[c]
			if !ok {
				return nil, &flagError{fmt.Sprintf("unknown flag `%s'", string(c))}
			}
			canarg := idx+utf8.RuneLen(c) == len(optname)
			if err := parseOption(d, canarg, argument); err != nil {
				return nil, err
			}
			argument = nil
		}
	}
	return positional, nil
}

func kindName(k optKind) string {
	switch k {
	case optInt:
		return "int"
	case optBool:
		return "bool"
	}
	return "string"
}
