func (k Key) String() string {
	var name string
	if k.Code == KeyRuneCode {
		name = string(k.Ch)
	} else if k.Code >= KeyCtrlA && k.Code <= KeyCtrlZ && k.Code != KeyBackspace && k.Code != KeyTab && k.Code != KeyEnter {
		name = "C-" + string(rune('a'+int(k.Code-KeyCtrlA)))
	} else if n, ok := keyDisplayNames[k.Code]; ok {
		name = n
	}
	prefix := ""
	if k.Mod&ModCtrl != 0 {
		prefix += "C-"
	}
	if k.Mod&ModShift != 0 {
		prefix += "S-"
	}
	if k.Mod&ModAlt != 0 {
		prefix += "M-"
	}
	return prefix + name
}

var errNoSuchKey = errors.New("no such key ")

// parseKey parses a single key name from the config file
func parseKey(s string) (Key, error) {
	orig := s
	var mod ModMask
	for {
		if strings.HasPrefix(s, "M-") {
			mod |= ModAlt
			s = s[2:]
			continue
		}
		if strings.HasPrefix(s, "S-") && len(s) > 2 {
			mod |= ModShift
			s = s[2:]
			continue
		}
		if strings.HasPrefix(s, "C-") && len(s) > 2 {
			if _, ok := nameToKey[s]; ok {
				break
			}
			mod |= ModCtrl
			s = s[2:]
			continue
		}
		break
	}
	if s == "" {
		return Key{}, fmt.Errorf("failed to convert '%s': %w", orig, errNoSuchKey)
	}
	if code, ok := nameToKey[s]; ok {
		return Key{Mod: mod, Code: code}, nil
	}
	r, _ := utf8.DecodeRuneInString(s)
	if r == utf8.RuneError {
		return Key{}, fmt.Errorf("failed to convert '%s': %w", orig, errNoSuchKey)
	}
	return Key{Mod: mod, Code: KeyRuneCode, Ch: r}, nil
}

// parseKeySequence parses "C-x,C-c" style sequences
func parseKeySequence(s string) ([]Key, error) {
	parts := strings.Split(s, ",")
	var keys []Key
	for _, p := range parts {
		if p == "" {
			return nil, fmt.Errorf("failed to convert '': %w", errNoSuchKey)
		}
		k, err := parseKey(p)
		if err != nil {
			return nil, err
		}
		keys = append(keys, k)
	}
	return keys, nil
}

var tcellNavKeys = map[tcell.Key]KeyCode{
	tcell.KeyUp:     KeyArrowUp,
	tcell.KeyDown:   KeyArrowDown,
	tcell.KeyLeft:   KeyArrowLeft,
	tcell.KeyRight:  KeyArrowRight,
	tcell.KeyHome:   KeyHome,
	tcell.KeyEnd:    KeyEnd,
	tcell.KeyPgUp:   KeyPgup,
	tcell.KeyPgDn:   KeyPgdn,
	tcell.KeyInsert: KeyInsert,
	tcell.KeyDelete: KeyDelete,
	tcell.KeyF1:     KeyF1,
	tcell.KeyF2:     KeyF2,
	tcell.KeyF3:     KeyF3,
	tcell.KeyF4:     KeyF4,
	tcell.KeyF5:     KeyF5,
	tcell.KeyF6:     KeyF6,
	tcell.KeyF7:     KeyF7,
	tcell.KeyF8:     KeyF8,
	tcell.KeyF9:     KeyF9,
	tcell.KeyF10:    KeyF10,
	tcell.KeyF11:    KeyF11,
	tcell.KeyF12:    KeyF12,
}

// convertKeyEvent converts a tcell key event to our key representation
func convertKeyEvent(ev *tcell.EventKey) (Key, bool) {
	tmod := ev.Modifiers()
	var mod ModMask
	if tmod&tcell.ModAlt != 0 || tmod&tcell.ModMeta != 0 {
		mod |= ModAlt
	}
	k := ev.Key()
	switch {
	case k == tcell.KeyRune:
		ch := ev.Rune()
		if tmod&tcell.ModCtrl != 0 {
			if ch >= 'a' && ch <= 'z' {
				return Key{Mod: mod, Code: KeyCtrlA + KeyCode(ch-'a')}, true
			}
			if ch >= 'A' && ch <= 'Z' {
				return Key{Mod: mod, Code: KeyCtrlA + KeyCode(ch-'A')}, true
			}
		}
		if ch == ' ' {
			return Key{Mod: mod, Code: KeySpace}, true
		}
		return Key{Mod: mod, Code: KeyRuneCode, Ch: ch}, true
	case k >= tcell.KeyCtrlA && k <= tcell.KeyCtrlZ:
		return Key{Mod: mod, Code: KeyCtrlA + KeyCode(k-tcell.KeyCtrlA)}, true
	case k == tcell.KeyBackspace || k == tcell.KeyBackspace2:
		return Key{Mod: mod, Code: KeyBackspace}, true
	case k == tcell.KeyTab || k == tcell.KeyBacktab:
		return Key{Mod: mod, Code: KeyTab}, true
	case k == tcell.KeyEnter:
		return Key{Mod: mod, Code: KeyEnter}, true
	case k == tcell.KeyEsc:
		return Key{Mod: mod, Code: KeyEsc}, true
	}
	if code, ok := tcellNavKeys[k]; ok {
		if tmod&tcell.ModCtrl != 0 {
			mod |= ModCtrl
		}
		if tmod&tcell.ModShift != 0 {
			mod |= ModShift
		}
		return Key{Mod: mod, Code: code}, true
	}
	return Key{}, false
}

// convertMouseEvent converts a tcell mouse event
func convertMouseEvent(ev *tcell.EventMouse) Key {
	b := ev.Buttons()
	var mod ModMask
	tmod := ev.Modifiers()
	if tmod&tcell.ModAlt != 0 {
		mod |= ModAlt
	}
	switch {
	case b&tcell.Button1 != 0:
		return Key{Mod: mod, Code: MouseLeft}
	case b&tcell.Button2 != 0:
		return Key{Mod: mod, Code: MouseMiddle}
	case b&tcell.Button3 != 0:
		return Key{Mod: mod, Code: MouseRight}
	}
	return Key{Mod: mod, Code: MouseNone}
}
EOF
