package main

import (
	"strconv"
	"strings"

	"github.com/pecoclone/peco/config"
)

// ansiSpan is a styled region of the stripped string (byte offsets)
type ansiSpan struct {
	start, end int
	fg, bg     config.Attribute
}

// parseANSI strips CSI sequences from s and returns the styled spans
func parseANSI(s string) (string, []ansiSpan) {
	if strings.IndexByte(s, 0x1b) < 0 {
		return s, nil
	}
	var b strings.Builder
	var spans []ansiSpan
	var fg, bg config.Attribute
	segStart := 0
	flush := func() {
		end := b.Len()
		if end > segStart && (fg != 0 || bg != 0) {
			spans = append(spans, ansiSpan{start: segStart, end: end, fg: fg, bg: bg})
		}
		segStart = end
	}
	i := 0
	for i < len(s) {
		c := s[i]
		if c == 0x1b && i+1 < len(s) && s[i+1] == '[' {
			// CSI
			j := i + 2
			for j < len(s) && s[j] >= 0x30 && s[j] <= 0x3f {
				j++
			}
			paramEnd := j
			for j < len(s) && s[j] >= 0x20 && s[j] <= 0x2f {
				j++
			}
			if j >= len(s) {
				// incomplete sequence: drop the rest
				i = len(s)
				break
			}
			final := s[j]
			if final >= 0x40 && final <= 0x7e {
				if final == 'm' && paramEnd == j {
					flush()
					fg, bg = applySGR(s[i+2:paramEnd], fg, bg)
				}
				i = j + 1
				continue
			}
			// invalid byte: drop sequence up to here
			i = j
			continue
		}
		if c == 0x1b && i+1 >= len(s) {
			// lone ESC at end
			b.WriteByte(c)
			i++
			continue
		}
		b.WriteByte(c)
		i++
	}
	flush()
	return b.String(), spans
}

func applySGR(params string, fg, bg config.Attribute) (config.Attribute, config.Attribute) {
	if params == "" {
		return 0, 0
	}
	parts := strings.Split(params, ";")
	nums := make([]int, len(parts))
	valid := make([]bool, len(parts))
	for i, p := range parts {
		if p == "" {
			nums[i] = 0
			valid[i] = true
			continue
		}
		n, err := strconv.Atoi(p)
		if err == nil {
			nums[i] = n
			valid[i] = true
		}
	}
	for i := 0; i < len(nums); i++ {
		if !valid[i] {
			continue
		}
		n := nums[i]
		switch {
		case n == 0:
			fg, bg = 0, 0
		case n == 1:
			fg |= config.AttrBold
		case n == 4:
			fg |= config.AttrUnderline
		case n == 7:
			fg |= config.AttrReverse
		case n >= 30 && n <= 37:
			fg = (fg &^ config.ColorMask) | config.Attribute(n-30+1)
		case n == 39:
			fg = fg &^ config.ColorMask
		case n >= 40 && n <= 47:
			bg = (bg &^ config.ColorMask) | config.Attribute(n-40+1)
		case n == 49:
			bg = bg &^ config.ColorMask
		case n == 38 || n == 48:
			if i+1 < len(nums) {
				mode := nums[i+1]
				if mode == 5 && i+2 < len(nums) {
					v := nums[i+2]
					if v >= 0 && v <= 255 {
						c := config.Attribute(v + 1)
						if n == 38 {
							fg = (fg &^ config.ColorMask) | c
						} else {
							bg = (bg &^ config.ColorMask) | c
						}
					}
					i += 2
				} else if mode == 2 && i+4 < len(nums) {
					r, g, bl := nums[i+2], nums[i+3], nums[i+4]
					c := config.AttrTrueColor | config.Attribute((r&0xff)<<16|(g&0xff)<<8|(bl&0xff))
					if n == 38 {
						fg = (fg &^ config.ColorMask) | c
					} else {
						bg = (bg &^ config.ColorMask) | c
					}
					i += 4
				} else {
					i++
				}
			}
		}
	}
	return fg, bg
}
EOF
echo ok"}

