package main

import (
	"bufio"
	"io"
	"sync"
)

// Source reads lines from the input
type Source struct {
	mu       sync.Mutex
	lines    []*Line
	nextID   int
	capacity int
	done     bool
	nullSep  bool
	ansi     bool
	maxBuf   int
	notify   chan struct{}
	doneCh   chan struct{}
	// generation increments when lines are dropped due to capacity
	dropped int
}

func newSource(capacity int, nullSep, ansi bool, maxBuf int) *Source {
	return &Source{
		capacity: capacity,
		nullSep:  nullSep,
		ansi:     ansi,
		maxBuf:   maxBuf,
		notify:   make(chan struct{}, 1),
		doneCh:   make(chan struct{}),
	}
}

func (s *Source) start(r io.Reader, closer func()) {
	go func() {
		defer func() {
			if closer != nil {
				closer()
			}
			s.mu.Lock()
			s.done = true
			s.mu.Unlock()
			close(s.doneCh)
			s.signal()
		}()
		sc := bufio.NewScanner(r)
		max := s.maxBuf
		if max <= 0 {
			max = 256 * 1024
		}
		initial := 4096
		if initial > max {
			initial = max
		}
		sc.Buffer(make([]byte, initial), max)
		for sc.Scan() {
			text := sc.Text()
			s.mu.Lock()
			l := newLine(s.nextID, text, s.nullSep, s.ansi)
			s.nextID++
			s.lines = append(s.lines, l)
			if s.capacity > 0 && len(s.lines) > s.capacity {
				n := len(s.lines) - s.capacity
				s.lines = append([]*Line(nil), s.lines[n:]...)
				s.dropped += n
			}
			s.mu.Unlock()
			s.signal()
		}
	}()
}

func (s *Source) signal() {
	select {
	case s.notify <- struct{}{}:
	default:
	}
}

// Snapshot returns the current lines and whether reading is done
func (s *Source) Snapshot() ([]*Line, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.lines, s.done
}

func (s *Source) Size() int {
	s.mu.Lock()
	defer s.mu.Unlock()
	return len(s.lines)
}

func (s *Source) IsDone() bool {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.done
}
