package main

import (
	"regexp"
	"sort"
	"strings"
	"unicode"
	"unicode/utf8"
)

// Matcher tests a line and returns match indices
type Matcher func(l *Line) ([][2]int, bool)

// Filter is a named filter type
type Filter interface {
	Name() string
	NewMatcher(query string) Matcher
}

func splitQuery(q string) (pos []string, neg []string) {
	for _, f := range strings.Fields(q) {
		if len(f) > 1 && f[0] == '-' {
			neg = append(neg, f[1:])
			continue
		}
		if strings.HasPrefix(f, "\\-") {
			f = f[1:]
		}
		pos = append(pos, f)
	}
	return
}

func hasUpper(s string) bool {
	for _, r := range s {
		if unicode.IsUpper(r) {
			return true
		}
	}
	return false
}

// RegexpFilter covers IgnoreCase, CaseSensitive, SmartCase, IRegexp, Regexp
type RegexpFilter struct {
	name      string
	flags     string
	quotemeta bool
	smart     bool
}

func (f *RegexpFilter) Name() string { return f.name }

func compileTerms(terms []string, flags string, quotemeta bool) ([]*regexp.Regexp, bool) {
	var res []*regexp.Regexp
	for _, t := range terms {
		pat := t
		if quotemeta {
			pat = regexp.QuoteMeta(t)
		}
		if flags != "" {
			pat = "(?" + flags + ")" + pat
		}
		rx, err := regexp.Compile(pat)
		if err != nil {
			return nil, false
		}
		res = append(res, rx)
	}
	return res, true
}

func (f *RegexpFilter) NewMatcher(query string) Matcher {
	flags := f.flags
	if f.smart {
		if hasUpper(query) {
			flags = ""
		} else {
			flags = "i"
		}
	}
	pos, neg := splitQuery(query)
	prx, ok1 := compileTerms(pos, flags, f.quotemeta)
	nrx, ok2 := compileTerms(neg, flags, f.quotemeta)
	if !ok1 || !ok2 {
		return func(l *Line) ([][2]int, bool) { return nil, false }
	}
	return func(l *Line) ([][2]int, bool) {
		s := l.display
		for _, rx := range nrx {
			if rx.MatchString(s) {
				return nil, false
			}
		}
		var all [][2]int
		for _, rx := range prx {
			m := rx.FindAllStringIndex(s, -1)
			if m == nil {
				return nil, false
			}
			for _, mm := range m {
				all = append(all, [2]int{mm[0], mm[1]})
			}
		}
		return mergeMatches(all), true
	}
}

func mergeMatches(all [][2]int) [][2]int {
	if len(all) == 0 {
		return nil
	}
	sort.SliceStable(all, func(i, j int) bool {
		if all[i][0] != all[j][0] {
			return all[i][0] < all[j][0]
		}
		return all[i][1] < all[j][1]
	})
	out := [][2]int{all[0]}
	for _, m := range all[1:] {
		last := &out[len(out)-1]
		if m[0] <= last[1] {
			if m[1] > last[1] {
				last[1] = m[1]
			}
			continue
		}
		out = append(out, m)
	}
	return out
}

// FuzzyFilter matches characters in order
type FuzzyFilter struct {
	longestSort bool
}

func (f *FuzzyFilter) Name() string { return "Fuzzy" }

func runeEqualFold(a, b rune) bool {
	if a == b {
		return true
	}
	return unicode.ToLower(a) == unicode.ToLower(b)
}

func (f *FuzzyFilter) NewMatcher(query string) Matcher {
	ignoreCase := !hasUpper(query)
	pos, neg := splitQuery(query)
	flags := ""
	if ignoreCase {
		flags = "i"
	}
	nrx, ok := compileTerms(neg, flags, true)
	if !ok {
		return func(l *Line) ([][2]int, bool) { return nil, false }
	}
	var pattern []rune
	for _, p := range pos {
		pattern = append(pattern, []rune(p)...)
	}
	return func(l *Line) ([][2]int, bool) {
		s := l.display
		for _, rx := range nrx {
			if rx.MatchString(s) {
				return nil, false
			}
		}
		var all [][2]int
		i := 0
		for _, pr := range pattern {
			found := false
			for i < len(s) {
				r, size := utf8.DecodeRuneInString(s[i:])
				if (ignoreCase && runeEqualFold(r, pr)) || (!ignoreCase && r == pr) {
					all = append(all, [2]int{i, i + size})
					i += size
					found = true
					break
				}
				i += size
			}
			if !found {
				return nil, false
			}
		}
		return mergeMatches(all), true
	}
}
