	queryTimerGen int

	frozen []*MatchedLine // base buffer when frozen

	loc         Location
	noHighlight bool

	selection   map[int]*Line
	rangeStart  int
	rangeMode   bool

	pendingKeys []Key

	statusMsg   string
	statusTimer *time.Timer
	statusGen   int

	xOffset int

	singleKeyJump bool

	// zoom state
	zoomed       bool
	zoomSaved    []*MatchedLine
	zoomSavedLine int

	// toggle query state
	queryToggled bool
	savedQuery   []rune
	savedCaret   int

	funcCh chan func()
	evCh   chan tcell.Event

	exitCode   int
	exiting    bool
	result     []string
	resultSet  bool

	lastSourceDraw time.Time
	sourceDrawScheduled bool
	sourceDone bool

	regionTop    int
	regionHeight int
	screenW      int
	screenH      int
}

func newPeco(opts *CLIOptions, args []string) *Peco {
	return &Peco{
		opts:       opts,
		args:       args,
		selection:  map[int]*Line{},
		rangeStart: -1,
		funcCh:     make(chan func(), 1024),
		evCh:       make(chan tcell.Event, 1024),
	}
}

func isValidLayout(s string) bool {
	return config.IsValidLayoutType(s)
}

func parseHeight(spec string) (*heightSpec, error) {
	s := strings.TrimSpace(spec)
	if s == "" {
		return nil, nil
	}
	if strings.HasSuffix(s, "%") {
		n, err := strconv.Atoi(s[:len(s)-1])
		if err != nil {
			return nil, fmt.Errorf("invalid height specification: %q", spec)
		}
		if n <= 0 {
			return nil, fmt.Errorf("height percentage must be positive: %q", spec)
		}
		if n > 100 {
			return nil, fmt.Errorf("height percentage must not exceed 100: %q", spec)
		}
		return &heightSpec{value: n, percent: true}, nil
	}
	n, err := strconv.Atoi(s)
	if err != nil {
		return nil, fmt.Errorf("invalid height specification: %q", spec)
	}
	if n <= 0 {
		return nil, fmt.Errorf("height must be positive: %q", spec)
	}
	return &heightSpec{value: n}, nil
}

func (p *Peco) setup() (int, bool) {
	opts := p.opts
	p.cfg.Init()

	rcfile := opts.OptRcfile
	if rcfile == "" {
		if f, err := config.LocateRcfile(); err == nil {
			rcfile = f
		}
	}
	if rcfile != "" {
		if err := p.cfg.ReadFilename(rcfile); err != nil {
			return errorExit("failed to setup peco: failed to setup configuration: failed to read config file: %s", err), false
		}
	}

	// apply configuration
	cfg := &p.cfg
	p.onCancel = cfg.OnCancel
	if opts.OptOnCancel != "" {
		v, err := config.ValidateOnCancel(opts.OptOnCancel)
		if err != nil {
			return errorExit("failed to setup peco: failed to apply configuration: invalid --on-cancel value: %s", err), false
		}
		p.onCancel = v
	}

	hspec := cfg.Height
	if opts.OptHeight != "" {
		hspec = opts.OptHeight
	}
	h, err := parseHeight(hspec)
	if err != nil {
		return errorExit("failed to setup peco: failed to apply configuration: failed to parse height specification: %s", err), false
	}
	p.height = h

	p.styles = cfg.Style
	p.prompt = cfg.Prompt
	if opts.OptPrompt != "" {
		p.prompt = opts.OptPrompt
	}
	if p.prompt == "" {
		p.prompt = "QUERY>"
	}
	p.layoutType = cfg.Layout
	if opts.OptLayout != "" {
		p.layoutType = opts.OptLayout
	}
	if p.layoutType == "" {
		p.layoutType = config.LayoutTopDown
	}
	p.selectionPrefix = cfg.SelectionPrefix
	if opts.OptSelectionPrefix != "" {
		p.selectionPrefix = opts.OptSelectionPrefix
	}
	p.execCmd = opts.OptExec
	p.printQuery = opts.OptPrintQuery
	p.enableANSI = cfg.ANSI || opts.OptANSI
	p.nullSep = opts.OptEnableNullSep
	p.bufferSize = opts.OptBufferSize
	p.stickySelection = cfg.StickySelection
	p.suppressStatus = cfg.SuppressStatusMsg
	p.fuzzyLongestSort = cfg.FuzzyLongestSort
	p.skjShowPrefix = cfg.SingleKeyJump.ShowPrefix
	p.queryExecDelay = 50 * time.Millisecond
	if cfg.QueryExecutionDelay > 0 {
		p.queryExecDelay = time.Duration(cfg.QueryExecutionDelay) * time.Millisecond
	}
	p.maxScanBuf = cfg.MaxScanBufferSize * 1024
	if cfg.MaxScanBufferSize <= 0 {
		p.maxScanBuf = 256 * 1024
	}
	p.initialIndex = opts.OptInitialIndex

	// derive the query cursor style
	p.cursorStyle = p.styles.QueryCursor
	if !p.styles.QueryCursor.Set {
		q := p.styles.Query
		if q.Fg == 0 && q.Bg == 0 {
			p.cursorStyle = config.Style{Fg: config.AttrReverse}
		} else {
			p.cursorStyle = config.Style{Fg: q.Bg, Bg: q.Fg}
		}
	}

	// keymap
	km, err := newKeymap(cfg)
	if err != nil {
		return errorExit("failed to setup peco: failed to apply configuration: failed to populate keymap: %s", err), false
	}
	p.keymap = km

	// filters
	p.filters = []Filter{
		&RegexpFilter{name: "IgnoreCase", flags: "i", quotemeta: true},
		&RegexpFilter{name: "CaseSensitive", quotemeta: true},
		&RegexpFilter{name: "SmartCase", quotemeta: true, smart: true},
		&RegexpFilter{name: "IRegexp", flags: "i"},
		&RegexpFilter{name: "Regexp"},
		&FuzzyFilter{longestSort: cfg.FuzzyLongestSort},
	}
	if len(cfg.CustomFilter) > 0 {
		names := make([]string, 0, len(cfg.CustomFilter))
		for n := range cfg.CustomFilter {
			names = append(names, n)
		}
		sort.Strings(names)
		for _, n := range names {
			c := cfg.CustomFilter[n]
			p.filters = append(p.filters, newExternalFilter(n, c))
		}
	}
	initial := cfg.InitialFilter
	if opts.OptInitialFilter != "" {
		initial = opts.OptInitialFilter
	}
	if initial == "" {
		initial = "IgnoreCase"
	}
	found := false
	for i, f := range p.filters {
		if f.Name() == initial {
			p.filterIdx = i
			found = true
			break
		}
	}
	if !found {
		return errorExit("failed to setup peco: failed to apply configuration: failed to populate initial filter: failed to set filter: specified filter was not found"), false
	}
	p.initialFilterIdx = p.filterIdx
	return 0, true
}

func (p *Peco) setupSource() (int, bool) {
	var r io.Reader
	var closer func()
	if len(p.args) > 0 {
		f, err := os.Open(p.args[0])
		if err != nil {
			return errorExit("failed to setup input source: failed to open file for input: %s", err), false
		}
		r = f
		closer = func() { f.Close() }
	} else {
		if isatty.IsTerminal(os.Stdin.Fd()) || isatty.IsCygwinTerminal(os.Stdin.Fd()) {
			return errorExit("failed to setup input source: you must supply something to work with via filename or stdin"), false
		}
		r = os.Stdin
	}
	p.inputReader = r
	p.inputCloser = closer
	return 0, true
}

// Run runs the application
func (p *Peco) Run() int {
	if code, ok := p.setup(); !ok {
		return code
	}
	if code, ok := p.setupSource(); !ok {
		return code
	}

	// in inline mode, disable the alternate screen
	var oldAlt string
	var hadAlt bool
	if p.height != nil {
		oldAlt, hadAlt = os.LookupEnv("TCELL_ALTSCREEN")
		os.Setenv("TCELL_ALTSCREEN", "disable")
	}
	restoreEnv := func() {
		if p.height != nil {
			if hadAlt {
				os.Setenv("TCELL_ALTSCREEN", oldAlt)
			} else {
				os.Unsetenv("TCELL_ALTSCREEN")
			}
		}
	}
	defer restoreEnv()

	scr, err := tcell.NewScreen()
	if err != nil {
		return errorExit("failed to initialize screen: failed to create tcell screen: %s", err)
	}
	p.screen = scr

	p.source = newSource(p.bufferSize, p.nullSep, p.enableANSI, p.maxScanBuf)
	p.source.start(p.inputReader, p.inputCloser)

	p.query = []rune(p.opts.OptQuery)
	p.caret = len(p.query)

	// immediate exit modes
	if p.opts.OptSelectAll || p.opts.OptSelect1 || p.opts.OptExitZero {
		<-p.source.doneCh
		lines, _ := p.source.Snapshot()
		if p.opts.OptExitZero && len(lines) == 0 {
			return 1
		}
		if p.opts.OptSelectAll || p.opts.OptSelect1 {
			matched := p.filterLinesSync(lines)
			if p.opts.OptSelectAll {
				var out []string
				for _, l := range matched {
					out = append(out, l.output)
				}
				p.writeResult(out)
				return 0
			}
			if len(matched) == 1 {
				p.writeResult([]string{matched[0].output})
				return 0
			}
		}
	}

	if err := scr.Init(); err != nil {
		return errorExit("failed to initialize screen: failed to initialize tcell screen: %s", err)
	}
	scr.EnableMouse()

	code := p.loop()
	p.finishScreen()
	if p.resultSet {
		p.writeResult(p.result)
	}
	return code
}

func (p *Peco) finishScreen() {
	if p.height != nil {
		// clear our region
		w, _ := p.screen.Size()
		for y := p.regionTop; y < p.regionTop+p.regionHeight; y++ {
			for x := 0; x < w; x++ {
				p.screen.SetContent(x, y, ' ', nil, tcell.StyleDefault)
			}
		}
		p.screen.ShowCursor(0, p.regionTop)
		p.screen.Show()
	}
	p.screen.Fini()
}

func (p *Peco) writeResult(lines []string) {
	var buf bytes.Buffer
	if p.printQuery {
		buf.WriteString(string(p.query))
		buf.WriteByte('\n')
	}
	for _, l := range lines {
		buf.WriteString(l)
		buf.WriteByte('\n')
	}
	os.Stdout.Write(buf.Bytes())
}

// filterLinesSync filters the given lines with the current query
func (p *Peco) filterLinesSync(lines []*Line) []*MatchedLine {
	q := string(p.query)
	var out []*MatchedLine
	if len(p.query) == 0 {
		for _, l := range lines {
			out = append(out, &MatchedLine{Line: l})
		}
		return out
	}
	f := p.filters[p.filterIdx]
	if ef, ok := f.(*ExternalFilter); ok {
		res, _ := ef.Run(q, lines, nil)
		return res
	}
	m := f.NewMatcher(q)
	for _, l := range lines {
		if mm, ok := m(l); ok {
			out = append(out, &MatchedLine{Line: l, matches: mm})
		}
	}
	if ff, ok := f.(*FuzzyFilter); ok && ff.longestSort {
		sortFuzzyLongest(out)
	}
	return out
}

func (p *Peco) runExec(lines []string) {
	var input bytes.Buffer
	for _, l := range lines {
		input.WriteString(l)
		input.WriteByte('\n')
	}
	p.screen.Suspend()
	cmd := exec.Command("/bin/sh", "-c", p.execCmd)
	cmd.Stdin = &input
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	_ = cmd.Run()
	p.screen.Resume()
}

var errNoTargets = errors.New("no targets or query. nothing to do")
EOF
echo ok

