package main

import (
	"fmt"

	"github.com/gdamore/tcell/v2"
	"github.com/mattn/go-runewidth"
	"github.com/pecoclone/peco/config"
)

func attrColor(a config.Attribute) tcell.Color {
	if a&config.AttrTrueColor != 0 {
		return tcell.NewHexColor(int32(a & config.ColorValueMask))
	}
	v := a & config.ColorValueMask
	if v == 0 {
		return tcell.ColorDefault
	}
	return tcell.PaletteColor(int(v - 1))
}

func toTcellStyle(fg, bg config.Attribute) tcell.Style {
	st := tcell.StyleDefault.Foreground(attrColor(fg)).Background(attrColor(bg))
	attrs := (fg | bg) & config.AttrMask
	if attrs&config.AttrBold != 0 {
		st = st.Bold(true)
	}
	if attrs&config.AttrUnderline != 0 {
		st = st.Underline(true)
	}
	if attrs&config.AttrReverse != 0 {
		st = st.Reverse(true)
	}
	return st
}

func styleOf(s config.Style) tcell.Style {
	return toTcellStyle(s.Fg, s.Bg)
}

func strWidth(s string) int {
	w := 0
	for _, r := range s {
		w += runewidth.RuneWidth(r)
	}
	return w
}

// computeRegion computes the area of the screen we use
func (p *Peco) computeRegion() {
	w, h := p.screen.Size()
	p.screenW, p.screenH = w, h
	if p.height == nil {
		p.regionTop = 0
		p.regionHeight = h
		return
	}
	var rh int
	if p.height.percent {
		rh = h * p.height.value / 100
	} else {
		rh = p.height.value + 2
	}
	if rh < 3 {
		rh = 3
	}
	if rh > h {
		rh = h
	}
	p.regionHeight = rh
	p.regionTop = h - rh
}

func (p *Peco) perPage() int {
	n := p.regionHeight - 2
	if n < 1 {
		n = 1
	}
	return n
}

func (p *Peco) promptRow() int {
	switch p.layoutType {
	case "bottom-up", "top-down-query-bottom":
		return p.regionTop + p.regionHeight - 2
	}
	return p.regionTop
}

func (p *Peco) statusRow() int {
	return p.regionTop + p.regionHeight - 1
}

// listRow returns the screen row for the i-th list line
func (p *Peco) listRow(i int) int {
	switch p.layoutType {
	case "bottom-up":
		return p.regionTop + p.regionHeight - 3 - i
	case "top-down-query-bottom":
		return p.regionTop + i
	}
	return p.regionTop + 1 + i
}

func (p *Peco) putStr(x, y int, s string, st tcell.Style) int {
	for _, r := range s {
		w := runewidth.RuneWidth(r)
		p.screen.SetContent(x, y, r, nil, st)
		x += w
	}
	return x
}

func (p *Peco) fillRow(y int, st tcell.Style) {
	for x := 0; x < p.screenW; x++ {
		p.screen.SetContent(x, y, ' ', nil, st)
	}
}

// calculatePage updates the location; returns false if nothing should be drawn
func (p *Peco) calculatePage() bool {
	perPage := p.perPage()
	loc := &p.loc
	total := len(p.current)
	loc.perPage = perPage
	loc.page = loc.lineNumber/perPage + 1
	loc.total = total
	if total == 0 {
		loc.maxPage = 1
	} else {
		loc.maxPage = (total + perPage - 1) / perPage
	}
	p.noHighlight = false
	if loc.maxPage < loc.page {
		if total == 0 {
			loc.offset = (loc.page - 1) * perPage
			return false
		}
		loc.page = loc.maxPage
		p.noHighlight = true
	} else if loc.lineNumber >= total && total > 0 {
		loc.lineNumber = total - 1
	}
	loc.offset = (loc.page - 1) * perPage
	return true
}

func (p *Peco) drawScreen() {
	if !p.calculatePage() {
		return
	}
	p.drawPrompt()
	p.drawList()
	p.drawStatus()
	if p.noHighlight {
		p.loc.lineNumber = len(p.current) - 1
		p.noHighlight = false
	}
}

func (p *Peco) drawPrompt() {
	y := p.promptRow()
	w := p.screenW
	queryStyle := styleOf(p.styles.Query)
	promptStyle := styleOf(p.styles.Prompt)
	cursorStyle := styleOf(p.cursorStyle)
	basicStyle := styleOf(p.styles.Basic)

	pw := strWidth(p.prompt)
	p.putStr(0, y, p.prompt, promptStyle)
	for x := pw; x < w; x++ {
		p.screen.SetContent(x, y, ' ', nil, queryStyle)
	}
	x := pw + 1
	cursorX := x
	for i, r := range p.query {
		st := queryStyle
		if i == p.caret {
			st = cursorStyle
			cursorX = x
		}
		p.screen.SetContent(x, y, r, nil, st)
		x += runewidth.RuneWidth(r)
	}
	if p.caret >= len(p.query) {
		cursorX = x
		p.screen.SetContent(x, y, ' ', nil, cursorStyle)
	}

	right := fmt.Sprintf("%s [%d (%d/%d)]", p.filters[p.filterIdx].Name(), p.loc.total, p.loc.page, p.loc.maxPage)
	p.putStr(w-strWidth(right), y, right, basicStyle)
	p.screen.ShowCursor(cursorX, y)
}

func (p *Peco) drawStatus() {
	y := p.statusRow()
	p.fillRow(y, tcell.StyleDefault)
	if p.statusMsg == "" {
		return
	}
	st := tcell.StyleDefault.Bold(true).Reverse(true)
	p.putStr(p.screenW-strWidth(p.statusMsg), y, p.statusMsg, st)
}

func (p *Peco) drawList() {
	perPage := p.perPage()
	basic := styleOf(p.styles.Basic)
	for i := 0; i < perPage; i++ {
		idx := p.loc.offset + i
		y := p.listRow(i)
		if idx >= len(p.current) {
			p.fillRow(y, basic)
			continue
		}
		ml := p.current[idx]
		isCursor := idx == p.loc.lineNumber && !p.noHighlight
		p.drawLine(y, ml, isCursor)
	}
}

func (p *Peco) isSelected(l *Line) bool {
	_, ok := p.selection[l.id]
	return ok
}

func (p *Peco) drawLine(y int, ml *MatchedLine, isCursor bool) {
	selected := p.isSelected(ml.Line) || p.inRange(ml)
	var lineStyle config.Style
	useANSI := false
	switch {
	case p.selectionPrefix != "":
		lineStyle = p.styles.Basic
		useANSI = true
	case isCursor:
		lineStyle = p.styles.Selected
	case selected:
		lineStyle = p.styles.SavedSelection
	case ml.context:
		lineStyle = p.styles.Context
	default:
		lineStyle = p.styles.Basic
		useANSI = true
	}
	ts := styleOf(lineStyle)
	p.fillRow(y, ts)

	startX := 0
	if p.selectionPrefix != "" {
		var prefix string
		if isCursor {
			prefix = p.selectionPrefix
		} else if selected {
			prefix = "*"
		}
		p.putStr(0, y, prefix, ts)
		startX = len(p.selectionPrefix) + 1
	}

	matchedFg := p.styles.Matched.Fg
	matchedBg := config.MergeAttribute(lineStyle.Bg, p.styles.Matched.Bg)
	matchStyle := toTcellStyle(matchedFg, matchedBg)

	s := ml.display
	col := 0
	mi := 0
	si := 0
	w := p.screenW
	for i, r := range s {
		inMatch := false
		for mi < len(ml.matches) && ml.matches[mi][1] <= i {
			mi++
		}
		if mi < len(ml.matches) && ml.matches[mi][0] <= i && i < ml.matches[mi][1] {
			inMatch = true
		}
		st := ts
		if inMatch {
			st = matchStyle
		} else if useANSI && len(ml.spans) > 0 {
			for si < len(ml.spans) && ml.spans[si].end <= i {
				si++
			}
			if si < len(ml.spans) && ml.spans[si].start <= i && i < ml.spans[si].end {
				sp := ml.spans[si]
				fg := lineStyle.Fg
				bg := lineStyle.Bg
				if sp.fg != 0 {
					fg = sp.fg
				}
				if sp.bg != 0 {
					bg = sp.bg
				}
				st = toTcellStyle(fg, bg)
			}
		}
		if r == '\t' {
			n := 4 - (col % 4)
			for k := 0; k < n; k++ {
				sx := startX + col - p.xOffset
				if sx >= startX && sx < w {
					p.screen.SetContent(sx, y, ' ', nil, st)
				}
				col++
			}
			continue
		}
		rw := runewidth.RuneWidth(r)
		sx := startX + col - p.xOffset
		if sx >= startX && sx < w {
			p.screen.SetContent(sx, y, r, nil, st)
		}
		col += rw
	}
}
EOF
echo ok"}

