	{"C-x,ArrowUp,ArrowUp,ArrowDown,ArrowDown,ArrowLeft,ArrowRight,ArrowLeft,ArrowRight,b,a", "peco.KonamiCommand"},
}

func (km *Keymap) bind(keys []Key, a Action) {
	n := km.root
	for _, k := range keys {
		if n.children == nil {
			n.children = map[Key]*keyNode{}
		}
		c, ok := n.children[k]
		if !ok {
			c = &keyNode{}
			n.children[k] = c
		}
		n = c
	}
	n.action = a
}

func (km *Keymap) unbind(keys []Key) {
	n := km.root
	for _, k := range keys {
		c, ok := n.children[k]
		if !ok {
			return
		}
		n = c
	}
	n.action = nil
}

// lookup returns the action for the sequence, and whether the sequence is
// a prefix of a longer sequence
func (km *Keymap) lookup(keys []Key) (Action, bool, bool) {
	n := km.root
	for _, k := range keys {
		c, ok := n.children[k]
		if !ok {
			return nil, false, false
		}
		n = c
	}
	if len(n.children) > 0 {
		return nil, true, true
	}
	return n.action, false, n.action != nil
}

func resolveAction(name string, cfg *config.Config, depth int) (Action, error) {
	if a, ok := actionRegistry[name]; ok {
		return a, nil
	}
	if list, ok := cfg.Action[name]; ok && depth < 32 {
		var acts []Action
		for _, n := range list {
			a, err := resolveAction(n, cfg, depth+1)
			if err != nil {
				return nil, err
			}
			acts = append(acts, a)
		}
		return func(p *Peco, k Key) {
			for _, a := range acts {
				if p.exiting {
					return
				}
				a(p, k)
			}
		}, nil
	}
	return nil, fmt.Errorf("could not resolve %s: no such action", name)
}

func newKeymap(cfg *config.Config) (*Keymap, error) {
	km := &Keymap{root: &keyNode{}}
	for _, kb := range defaultKeyBinding {
		keys, err := parseKeySequence(kb[0])
		if err != nil {
			panic(err)
		}
		a := actionRegistry[kb[1]]
		km.bind(keys, a)
	}
	for ks, an := range cfg.Keymap {
		keys, err := parseKeySequence(ks)
		if err != nil {
			return nil, fmt.Errorf("failed to apply key bindings: unknown key %s: %w", ks, err)
		}
		if an == "-" {
			km.unbind(keys)
			continue
		}
		a, err := resolveAction(an, cfg, 0)
		if err != nil {
			return nil, fmt.Errorf("failed to apply key bindings: failed to resolve action name %s: %w", an, err)
		}
		km.bind(keys, a)
	}
	return km, nil
}

func joinKeys(keys []Key) string {
	parts := make([]string, len(keys))
	for i, k := range keys {
		parts[i] = k.String()
	}
	return strings.Join(parts, " ")
}
