package main

import (
	"time"

	"github.com/gdamore/tcell/v2"
)

func (p *Peco) post(f func()) {
	p.funcCh <- f
}

func (p *Peco) loop() int {
	scr := p.screen
	go func() {
		for {
			ev := scr.PollEvent()
			if ev == nil {
				return
			}
			p.evCh <- ev
		}
	}()

	p.computeRegion()
	p.loc.lineNumber = p.initialIndex
	if p.loc.lineNumber < 0 {
		p.loc.lineNumber = 0
	}
	p.refreshFromSource(true)
	if len(p.query) > 0 {
		p.startFilter()
	}
	p.drawScreen()
	scr.Show()

	ticker := time.NewTicker(100 * time.Millisecond)
	defer ticker.Stop()
	pendingSource := false

	for !p.exiting {
		select {
		case ev := <-p.evCh:
			p.handleEvent(ev)
		case f := <-p.funcCh:
			f()
		case <-p.source.notify:
			if !p.sourceDone && p.source.IsDone() {
				p.sourceDone = true
				p.refreshFromSource(false)
				pendingSource = false
			} else if time.Since(p.lastSourceDraw) >= 100*time.Millisecond {
				p.refreshFromSource(false)
				pendingSource = false
			} else {
				pendingSource = true
			}
		case <-ticker.C:
			if pendingSource {
				p.refreshFromSource(false)
				pendingSource = false
			}
		}
		if !p.exiting {
			scr.Show()
		}
	}
	return p.exitCode
}

// sourceLines wraps the source lines as matched lines (no matches)
var sourceCache []*MatchedLine
var sourceCacheFirst = -1

func (p *Peco) sourceBuffer() []*MatchedLine {
	lines, _ := p.source.Snapshot()
	if len(lines) == 0 {
		sourceCache = nil
		return nil
	}
	if sourceCacheFirst != lines[0].id || len(sourceCache) > len(lines) {
		sourceCache = nil
		sourceCacheFirst = lines[0].id
	}
	for i := len(sourceCache); i < len(lines); i++ {
		sourceCache = append(sourceCache, &MatchedLine{Line: lines[i]})
	}
	return sourceCache[:len(lines):len(lines)]
}

// baseBuffer is what the filter operates on (frozen results or source)
func (p *Peco) baseBuffer() []*MatchedLine {
	if p.frozen != nil {
		return p.frozen
	}
	return p.sourceBuffer()
}

func (p *Peco) refreshFromSource(initial bool) {
	p.lastSourceDraw = time.Now()
	if p.isFiltered || p.zoomed {
		return
	}
	if p.frozen != nil {
		return
	}
	p.current = p.sourceBuffer()
	if !initial {
		p.drawScreen()
	}
}

func (p *Peco) handleEvent(ev tcell.Event) {
	switch e := ev.(type) {
	case *tcell.EventKey:
		k, ok := convertKeyEvent(e)
		if !ok {
			return
		}
		p.handleKey(k)
	case *tcell.EventMouse:
		k := convertMouseEvent(e)
		p.handleKey(k)
	case *tcell.EventResize:
		p.screen.Sync()
		p.computeRegion()
		p.drawScreen()
	}
}

func (p *Peco) handleKey(k Key) {
	if p.singleKeyJump {
		if p.handleSingleKeyJump(k) {
			return
		}
	}
	p.pendingKeys = append(p.pendingKeys, k)
	act, isPrefix, _ := p.keymap.lookup(p.pendingKeys)
	seq := joinKeys(p.pendingKeys)
	if isPrefix {
		p.setStatus(seq, 0)
		return
	}
	p.pendingKeys = nil
	p.setStatus(seq, 500*time.Millisecond)
	if act != nil {
		act(p, k)
		return
	}
	p.acceptChar(k)
}

func (p *Peco) setStatus(msg string, clearDelay time.Duration) {
	if p.suppressStatus {
		return
	}
	p.statusGen++
	if p.statusTimer != nil {
		p.statusTimer.Stop()
		p.statusTimer = nil
	}
	p.statusMsg = msg
	p.drawStatus()
	if clearDelay > 0 {
		gen := p.statusGen
		p.statusTimer = time.AfterFunc(clearDelay, func() {
			p.post(func() {
				if p.statusGen != gen {
					return
				}
				p.statusMsg = ""
				p.drawStatus()
			})
		})
	}
}

func (p *Peco) acceptChar(k Key) {
	var ch rune
	switch k.Code {
	case KeyRuneCode:
		ch = k.Ch
	case KeySpace:
		ch = ' '
	default:
		return
	}
	q := make([]rune, 0, len(p.query)+1)
	q = append(q, p.query[:p.caret]...)
	q = append(q, ch)
	q = append(q, p.query[p.caret:]...)
	p.query = q
	p.caret++
	p.drawPrompt()
	p.execQuery()
}

func (p *Peco) cancelQueryTimer() {
	p.queryTimerGen++
	if p.queryTimer != nil {
		p.queryTimer.Stop()
		p.queryTimer = nil
	}
}

func (p *Peco) cancelFilter() {
	p.filterGen++
	if p.filterCancel != nil {
		close(p.filterCancel)
		p.filterCancel = nil
	}
	p.filterRunning = false
}

func (p *Peco) execQuery() {
	p.cancelQueryTimer()
	if p.zoomed {
		p.zoomed = false
		p.zoomSaved = nil
	}
	if len(p.query) == 0 {
		p.cancelFilter()
		p.isFiltered = false
		p.current = p.baseBuffer()
		p.drawScreen()
		return
	}
	gen := p.queryTimerGen
	p.queryTimer = time.AfterFunc(p.queryExecDelay, func() {
		p.post(func() {
			if gen != p.queryTimerGen {
				return
			}
			p.startFilter()
		})
	})
}

// startFilter runs the current filter against the base buffer
func (p *Peco) startFilter() {
	p.cancelFilter()
	if !p.stickySelection {
		p.selection = map[int]*Line{}
	}
	gen := p.filterGen
	cancel := make(chan struct{})
	p.filterCancel = cancel
	query := string(p.query)
	f := p.filters[p.filterIdx]
	frozen := p.frozen
	src := p.source
	p.filterRunning = true
	p.setStatus("Running query...", 0)

	go func() {
		var results []*MatchedLine
		var matcher Matcher
		ef, isExternal := f.(*ExternalFilter)
		if !isExternal {
			matcher = f.NewMatcher(query)
		}
		processed := 0
		lastPost := time.Now()
		for {
			var base []*MatchedLine
			done := true
			if frozen != nil {
				base = frozen
			} else {
				lines, d := src.Snapshot()
				done = d
				base = make([]*MatchedLine, 0, len(lines)-processed)
				for i := processed; i < len(lines); i++ {
					base = append(base, &MatchedLine{Line: lines[i]})
				}
				processed = len(lines)
			}
			if isExternal {
				ls := make([]*Line, len(base))
				for i, b := range base {
					ls[i] = b.Line
				}
				res, ok := ef.Run(query, ls, cancel)
				if !ok {
					return
				}
				results = append(results, res...)
			} else {
				for i, b := range base {
					if i%1000 == 0 {
						select {
						case <-cancel:
							return
						default:
						}
					}
					if mm, ok := matcher(b.Line); ok {
						results = append(results, &MatchedLine{Line: b.Line, matches: mm})
					}
				}
			}
			if done {
				break
			}
			if time.Since(lastPost) > 100*time.Millisecond {
				lastPost = time.Now()
				snapshot := append([]*MatchedLine(nil), results...)
				p.post(func() {
					if gen != p.filterGen {
						return
					}
					p.current = snapshot
					p.isFiltered = true
					p.drawScreen()
				})
			}
			select {
			case <-cancel:
				return
			case <-time.After(20 * time.Millisecond):
			}
		}
		if ff, ok := f.(*FuzzyFilter); ok && ff.longestSort {
			sortFuzzyLongest(results)
		}
		p.post(func() {
			if gen != p.filterGen {
				return
			}
			p.filterRunning = false
			p.filterCancel = nil
			p.current = results
			p.isFiltered = true
			p.filterQuery = query
			p.drawScreen()
			p.setStatus("", 0)
		})
	}()
}
EOF
echo ok

