// ---- query editing ----

func doForwardChar(p *Peco, _ Key) {
	if p.caret >= len(p.query) {
		return
	}
	p.caret++
	p.drawPrompt()
}

func doBackwardChar(p *Peco, _ Key) {
	if p.caret <= 0 {
		return
	}
	p.caret--
	p.drawPrompt()
}

func doBeginningOfLine(p *Peco, _ Key) {
	p.caret = 0
	p.drawPrompt()
}

func doEndOfLine(p *Peco, _ Key) {
	p.caret = len(p.query)
	p.drawPrompt()
}

func isWordSep(r rune) bool {
	return unicode.IsSpace(r)
}

func doForwardWord(p *Peco, _ Key) {
	if p.caret >= len(p.query) {
		return
	}
	i := p.caret
	for i < len(p.query) && isWordSep(p.query[i]) {
		i++
	}
	for i < len(p.query) && !isWordSep(p.query[i]) {
		i++
	}
	p.caret = i
	p.drawPrompt()
}

func doBackwardWord(p *Peco, _ Key) {
	if p.caret <= 0 {
		return
	}
	i := p.caret
	for i > 0 && isWordSep(p.query[i-1]) {
		i--
	}
	for i > 0 && !isWordSep(p.query[i-1]) {
		i--
	}
	p.caret = i
	p.drawPrompt()
}

func (p *Peco) setQuery(q []rune, caret int) {
	p.query = q
	p.caret = caret
}

func doDeleteForwardChar(p *Peco, _ Key) {
	if p.caret >= len(p.query) {
		return
	}
	q := append([]rune{}, p.query[:p.caret]...)
	q = append(q, p.query[p.caret+1:]...)
	p.setQuery(q, p.caret)
	p.execQuery()
}

func doDeleteBackwardChar(p *Peco, _ Key) {
	if p.caret <= 0 || len(p.query) == 0 {
		return
	}
	q := append([]rune{}, p.query[:p.caret-1]...)
	q = append(q, p.query[p.caret:]...)
	p.setQuery(q, p.caret-1)
	p.execQuery()
}

func doDeleteForwardWord(p *Peco, _ Key) {
	if p.caret >= len(p.query) {
		return
	}
	i := p.caret
	for i < len(p.query) && isWordSep(p.query[i]) {
		i++
	}
	for i < len(p.query) && !isWordSep(p.query[i]) {
		i++
	}
	q := append([]rune{}, p.query[:p.caret]...)
	q = append(q, p.query[i:]...)
	p.setQuery(q, p.caret)
	p.execQuery()
}

func doDeleteBackwardWord(p *Peco, _ Key) {
	if p.caret <= 0 || len(p.query) == 0 {
		return
	}
	i := p.caret
	for i > 0 && isWordSep(p.query[i-1]) {
		i--
	}
	for i > 0 && !isWordSep(p.query[i-1]) {
		i--
	}
	q := append([]rune{}, p.query[:i]...)
	q = append(q, p.query[p.caret:]...)
	p.setQuery(q, i)
	p.execQuery()
}

func doKillBeginningOfLine(p *Peco, _ Key) {
	q := append([]rune{}, p.query[p.caret:]...)
	p.setQuery(q, 0)
	p.execQuery()
}

func doKillEndOfLine(p *Peco, _ Key) {
	if p.caret >= len(p.query) {
		return
	}
	q := append([]rune{}, p.query[:p.caret]...)
	p.setQuery(q, p.caret)
	p.execQuery()
}

func doDeleteAll(p *Peco, _ Key) {
	p.setQuery([]rune{}, 0)
	p.execQuery()
}

func doEndOfFile(p *Peco, k Key) {
	if len(p.query) == 0 {
		doCancel(p, k)
		return
	}
	doDeleteForwardChar(p, k)
}

func doRefreshScreen(p *Peco, _ Key) {
	p.screen.Sync()
	p.execQuery()
	p.drawScreen()
}

// ---- cursor movement ----

func (p *Peco) bottomUp() bool {
	return p.layoutType == "bottom-up"
}

func (p *Peco) moveLine(delta int) {
	total := len(p.current)
	if total == 0 {
		return
	}
	n := p.loc.lineNumber + delta
	if n < 0 {
		n = total - 1
	} else if n >= total {
		n = 0
	}
	p.setLineNumber(n)
}

func (p *Peco) setLineNumber(n int) {
	p.loc.lineNumber = n
	p.updateRange()
	p.drawScreen()
}

func doSelectUp(p *Peco, _ Key) {
	if p.bottomUp() {
		p.moveLine(1)
	} else {
		p.moveLine(-1)
	}
}

func doSelectDown(p *Peco, _ Key) {
	if p.bottomUp() {
		p.moveLine(-1)
	} else {
		p.moveLine(1)
	}
}

func (p *Peco) movePage(dir int) {
	total := len(p.current)
	if total == 0 {
		return
	}
	n := p.loc.lineNumber + dir*p.perPage()
	if n < 0 {
		n = total - 1
	} else if n >= total {
		n = 0
	}
	p.setLineNumber(n)
}

func doScrollPageDown(p *Peco, _ Key) {
	if p.bottomUp() {
		p.movePage(-1)
	} else {
		p.movePage(1)
	}
}

func doScrollPageUp(p *Peco, _ Key) {
	if p.bottomUp() {
		p.movePage(1)
	} else {
		p.movePage(-1)
	}
}

func doScrollFirstItem(p *Peco, _ Key) {
	if len(p.current) == 0 {
		return
	}
	p.setLineNumber(0)
}

func doScrollLastItem(p *Peco, _ Key) {
	if len(p.current) == 0 {
		return
	}
	p.setLineNumber(len(p.current) - 1)
}

func (p *Peco) maxLineWidth() int {
	m := 0
	for _, l := range p.current {
		w := displayWidth(l.display)
		if w > m {
			m = w
		}
	}
	return m
}

func doScrollRight(p *Peco, _ Key) {
	step := p.screenW / 2
	max := p.maxLineWidth() - p.screenW
	if max < 0 {
		max = 0
	}
	n := p.xOffset + step
	if n > max {
		n = max
	}
	p.xOffset = n
	p.drawScreen()
}

func doScrollLeft(p *Peco, _ Key) {
	step := p.screenW / 2
	n := p.xOffset - step
	if n < 0 {
		n = 0
	}
	p.xOffset = n
	p.drawScreen()
}

// ---- selection ----

func (p *Peco) currentLine() *MatchedLine {
	if p.loc.lineNumber < 0 || p.loc.lineNumber >= len(p.current) {
		return nil
	}
	return p.current[p.loc.lineNumber]
}

func doToggleSelection(p *Peco, _ Key) {
	l := p.currentLine()
	if l == nil || l.context {
		return
	}
	if p.isSelected(l.Line) {
		delete(p.selection, l.id)
	} else {
		p.selection[l.id] = l.Line
	}
	p.drawScreen()
}

func doToggleSelectionAndSelectNext(p *Peco, k Key) {
	doToggleSelection(p, k)
	doSelectDown(p, k)
}

func doSelectNone(p *Peco, _ Key) {
	p.selection = map[int]*Line{}
	p.drawScreen()
}

func doSelectAll(p *Peco, _ Key) {
	for _, l := range p.current {
		if l.context {
			continue
		}
		p.selection[l.id] = l.Line
	}
	p.drawScreen()
}

func doSelectVisible(p *Peco, _ Key) {
	perPage := p.perPage()
	for i := 0; i < perPage; i++ {
		idx := p.loc.offset + i
		if idx >= len(p.current) {
			break
		}
		l := p.current[idx]
		if l.context {
			continue
		}
		p.selection[l.id] = l.Line
	}
	p.drawScreen()
}

func doInvertSelection(p *Peco, _ Key) {
	for _, l := range p.current {
		if l.context {
			continue
		}
		if p.isSelected(l.Line) {
			delete(p.selection, l.id)
		} else {
			p.selection[l.id] = l.Line
		}
	}
	p.drawScreen()
}

func (p *Peco) inRange(ml *MatchedLine) bool {
	if !p.rangeMode || p.rangeStart < 0 {
		return false
	}
	return false
}

func (p *Peco) updateRange() {}

func doToggleRangeMode(p *Peco, _ Key) {
	if p.rangeMode {
		p.rangeMode = false
		p.rangeStart = -1
	} else {
		p.rangeMode = true
		p.rangeStart = p.loc.lineNumber
	}
	p.drawScreen()
}

func doCancelRangeMode(p *Peco, _ Key) {
	p.rangeMode = false
	p.rangeStart = -1
	p.drawScreen()
}

func (p *Peco) selectedIndices() []int {
	var idx []int
	for i, l := range p.current {
		if p.isSelected(l.Line) {
			idx = append(idx, i)
		}
	}
	return idx
}

func doGoToNextSelection(p *Peco, _ Key) {
	if len(p.selection) == 0 {
		p.setStatus("No Selection", 0)
		return
	}
	idx := p.selectedIndices()
	if len(idx) == 0 {
		p.setStatus("No Selection", 0)
		return
	}
	for _, i := range idx {
		if i > p.loc.lineNumber {
			p.setLineNumber(i)
			p.setStatus("Next Selection", 0)
			return
		}
	}
	p.setLineNumber(idx[0])
	p.setStatus("Next Selection (first)", 0)
}

func doGoToPreviousSelection(p *Peco, _ Key) {
	if len(p.selection) == 0 {
		p.setStatus("No Selection", 0)
		return
	}
	idx := p.selectedIndices()
	if len(idx) == 0 {
		p.setStatus("No Selection", 0)
		return
	}
	for j := len(idx) - 1; j >= 0; j-- {
		if idx[j] < p.loc.lineNumber {
			p.setLineNumber(idx[j])
			p.setStatus("Previous Selection", 0)
			return
		}
	}
	p.setLineNumber(idx[len(idx)-1])
	p.setStatus("Previous Selection (first)", 0)
}

// ---- filters ----

func doRotateFilter(p *Peco, _ Key) {
	p.filterIdx = (p.filterIdx + 1) % len(p.filters)
	p.execQueryNow()
