		}
		sort.Slice(ls, func(i, j int) bool { return ls[i].id < ls[j].id })
		for _, l := range ls {
			out = append(out, l.output)
		}
		return out
	}
	if l := p.currentLine(); l != nil {
		out = append(out, l.output)
	}
	return out
}

func doFinish(p *Peco, _ Key) {
	res := p.collectResult()
	if p.execCmd != "" {
		p.runExec(res)
		p.drawScreen()
		return
	}
	p.result = res
	p.resultSet = true
	p.exitCode = 0
	p.exiting = true
}

func doCancel(p *Peco, _ Key) {
	if p.rangeMode {
		doCancelRangeMode(p, Key{})
		return
	}
	p.exiting = true
	if p.onCancel == "error" {
		p.exitCode = 1
	} else {
		p.exitCode = 0
	}
}

var _ = time.Second
