		p.query = p.savedQuery
		p.savedQuery = nil
		if p.caret > len(p.query) {
			p.caret = len(p.query)
		}
	}
	p.execQueryNow()
}

func doViewAround(p *Peco, k Key) {
	l := p.currentLine()
	if len(p.query) == 0 {
		return
	}
	p.query = []rune{}
	p.caret = 0
	p.drawPrompt()
	p.cancelQueryTimer()
	p.cancelFilter()
	p.zoomed = false
	p.zoomSaved = nil
	p.isFiltered = false
	p.current = p.baseBuffer()
	if l != nil {
		for i, ml := range p.current {
			if ml.id == l.id {
				p.loc.lineNumber = i
				break
			}
		}
	}
	p.drawScreen()
}

func doFreezeResults(p *Peco, _ Key) {
	p.frozen = append([]*MatchedLine(nil), p.current...)
	p.invalidateCache()
	p.cancelQueryTimer()
	p.cancelFilter()
	p.query = []rune{}
	p.caret = 0
	p.isFiltered = false
	p.zoomed = false
	p.zoomSaved = nil
	p.current = p.frozen
	p.drawScreen()
	p.setStatus("Results frozen", 0)
}

func doUnfreezeResults(p *Peco, _ Key) {
	if p.frozen == nil {
		p.setStatus("No frozen results", 0)
		return
	}
	p.frozen = nil
	p.invalidateCache()
	p.cancelQueryTimer()
	p.cancelFilter()
	p.query = []rune{}
	p.caret = 0
	p.isFiltered = false
	p.zoomed = false
	p.zoomSaved = nil
	p.current = p.baseBuffer()
	p.drawScreen()
	p.setStatus("Results unfrozen", 0)
}

func doZoomIn(p *Peco, _ Key) {
	if p.zoomed {
		p.setStatus("Already zoomed in", 0)
		return
	}
	if len(p.query) == 0 || !p.isFiltered || len(p.current) == 0 {
		p.setStatus("Nothing to zoom into", 0)
		return
	}
	src := p.baseBuffer()
	pos := map[int]int{}
	for i, ml := range src {
		pos[ml.id] = i
	}
	matched := map[int]*MatchedLine{}
	var ranges [][2]int
	for _, ml := range p.current {
		i, ok := pos[ml.id]
		if !ok {
			continue
		}
		matched[ml.id] = ml
		lo, hi := i-3, i+3
		if lo < 0 {
			lo = 0
		}
		if hi > len(src)-1 {
			hi = len(src) - 1
		}
		if n := len(ranges); n > 0 && lo <= ranges[n-1][1]+1 {
			if hi > ranges[n-1][1] {
				ranges[n-1][1] = hi
			}
		} else {
			ranges = append(ranges, [2]int{lo, hi})
		}
	}
	var out []*MatchedLine
	cur := p.currentLine()
	newCursor := 0
	for _, r := range ranges {
		for i := r[0]; i <= r[1]; i++ {
			l := src[i]
			if m, ok := matched[l.id]; ok {
				if cur != nil && cur.id == m.id {
					newCursor = len(out)
				}
				out = append(out, m)
			} else {
				out = append(out, &MatchedLine{Line: l.Line, context: true})
			}
		}
	}
	p.zoomSaved = p.current
	p.zoomSavedLine = p.loc.lineNumber
	p.zoomed = true
	p.current = out
	p.loc.lineNumber = newCursor
	p.drawScreen()
}

func doZoomOut(p *Peco, _ Key) {
	if !p.zoomed {
		p.setStatus("Not zoomed in", 0)
		return
	}
	p.current = p.zoomSaved
	p.loc.lineNumber = p.zoomSavedLine
	p.zoomed = false
	p.zoomSaved = nil
	p.drawScreen()
}

