func (f *ExternalFilter) NewMatcher(query string) Matcher {
	return func(l *Line) ([][2]int, bool) { return nil, false }
}

// Run runs the external filter over the lines
func (f *ExternalFilter) Run(query string, lines []*Line, cancel chan struct{}) ([]*MatchedLine, bool) {
